(function(t){t.JobLabContent=Object.assign(t.JobLabContent||{},{"KK-639":{scenario:{company:"Tầng Sâu Geotechnical Services",supervisor:{name:"Hồ Sỹ Tuấn",role:{vi:"Chủ nhiệm địa kỹ thuật",en:"Principal Geotechnical Engineer"}},ref_code:"GEO-BH07",title:{vi:"Phân loại đúng đất. Tính đúng ứng suất hữu hiệu.",en:"Classify the soil right. Compute effective stress right."},brief:{vi:"Bạn soát xét báo cáo GEO-BH07 phục vụ thiết kế cọc khoan nhồi. Hố khoan BH-07: lớp 1 từ 0 đến 1,5 m, γ = 18,5 kN/m3; mực nước ngầm ổn định ở -1,5 m; lớp 2 sét từ 1,5 đến 9,5 m, γsat = 18,8 kN/m3, LL = 58%, PL = 28%; lớp 3 cát từ 9,5 đến 21,5 m, γsat = 19,6 kN/m3. Mũi cọc ở -21,5 m. Hãy sửa ký hiệu phân loại lớp 2 và ứng suất hữu hiệu thẳng đứng tại mũi cọc (kPa), rồi lập báo cáo có căn cứ.",en:"You are reviewing report GEO-BH07 for bored pile design. Borehole BH-07: layer 1 from 0 to 1.5 m, γ = 18.5 kN/m3; stable groundwater at -1.5 m; layer 2 clay from 1.5 to 9.5 m, γsat = 18.8 kN/m3, LL = 58%, PL = 28%; layer 3 sand from 9.5 to 21.5 m, γsat = 19.6 kN/m3. The pile toe is at -21.5 m. Correct the layer 2 classification symbol and the vertical effective stress at the pile toe (kPa), then write an evidence-based report."},reference_title:{vi:"Nhật ký hố khoan BH-07 & kết quả thí nghiệm đã duyệt",en:"Approved BH-07 borehole log & laboratory results"},fields:[{id:"SOIL_L2",label:{vi:"Ký hiệu phân loại USCS lớp 2",en:"USCS symbol of layer 2"},initial:"USCS-CL",expected:"USCS-CH",choices:["USCS-CL","USCS-CH","USCS-MH"],reference:"Phiếu kết quả giới hạn Atterberg",ref_value:{vi:"Lớp 2: LL = 58%, PL = 28%; biểu đồ dẻo Casagrande, đường A: PI = 0,73 x (LL - 20)",en:"Layer 2: LL = 58%, PL = 28%; Casagrande plasticity chart, A-line: PI = 0.73 x (LL - 20)"},hint:{vi:"Tính PI = LL - PL, so với đường A và ranh giới LL = 50% trước khi chọn ký hiệu.",en:"Compute PI = LL - PL, then compare with the A-line and the LL = 50% boundary before choosing."}},{id:"SIGMA_V",label:{vi:"Ứng suất hữu hiệu tại mũi cọc (kPa)",en:"Effective stress at pile toe (kPa)"},initial:"413.35",expected:"213.35",reference:"Bảng tính ứng suất theo chiều sâu",ref_value:{vi:"Lớp 1: 1,5 m, γ 18,5; lớp 2: 8 m, γsat 18,8; lớp 3: 12 m, γsat 19,6; nước ngầm -1,5 m",en:"Layer 1: 1.5 m, γ 18.5; layer 2: 8 m, γsat 18.8; layer 3: 12 m, γsat 19.6; groundwater -1.5 m"},hint:{vi:"Bản nháp dùng trọng lượng riêng bão hòa cho cả phần dưới mực nước, tức là đang tính ứng suất tổng.",en:"The draft used saturated unit weights below the water table, which gives total stress."}}],sop32:{vi:"Trên mực nước ngầm dùng γ; dưới mực nước ngầm dùng γ' = γsat - γw với γw = 10 kN/m3 (mô phỏng). σ'v = tổng γ x chiều dày của từng lớp đến cao độ mũi cọc; ghi đến 0,01 kPa.",en:"Above groundwater use γ; below it use γ' = γsat - γw with γw = 10 kN/m3 (simulated). σ'v = sum of unit weight x thickness of each layer down to the pile toe; state to 0.01 kPa."},context:{label:"GEO-DB / BH-07",metrics:[{label:{vi:"Mực nước ngầm",en:"Groundwater level"},value:"-1.5 m"},{label:{vi:"Cao độ mũi cọc",en:"Pile toe level"},value:"-21.5 m"},{label:{vi:"Đường kính cọc",en:"Pile diameter"},value:"1000 mm"}]},terminal:{system:"geo-db",settable:["SOIL_L2","SIGMA_V"],commands:[{cmd:"status",out:{vi:"Báo cáo GEO-BH07 (nháp): lớp 2 = USCS-CL; σ'v tại mũi cọc = 413,35 kPa; trạng thái: chờ soát xét",en:"Report GEO-BH07 (draft): layer 2 = USCS-CL; toe σ'v = 413.35 kPa; status: pending review"}},{cmd:"cat bh-07.log",out:{vi:"0-1,5 m: đất lấp, γ 18,5; 1,5-9,5 m: sét xám xanh dẻo mềm, γsat 18,8; 9,5-21,5 m: cát hạt trung chặt vừa, γsat 19,6",en:"0-1.5 m: fill, γ 18.5; 1.5-9.5 m: soft grey-green clay, γsat 18.8; 9.5-21.5 m: medium dense medium sand, γsat 19.6"}},{cmd:"lab atterberg l2",out:{vi:"Mẫu UD-07-3 lớp 2: LL = 58%, PL = 28%, độ ẩm tự nhiên 49%",en:"Sample UD-07-3 layer 2: LL = 58%, PL = 28%, natural moisture content 49%"}},{cmd:"cat gwt.txt",out:{vi:"Mực nước ngầm ổn định đo sau 24 giờ: -1,5 m so với mặt đất tự nhiên",en:"Stable groundwater measured after 24 h: -1.5 m below natural ground"}},{cmd:"calc stress --draft",out:{vi:"Bản nháp: σ = 18,5 x 1,5 + 18,8 x 8 + 19,6 x 12 = 413,35 kPa (chưa trừ áp lực nước lỗ rỗng)",en:"Draft: σ = 18.5 x 1.5 + 18.8 x 8 + 19.6 x 12 = 413.35 kPa (pore water pressure not deducted)"}}]},crisis:{vi:"Nhà thầu cọc nhắn: “Sửa SPT lớp cát lên trên 50 và giữ số ứng suất nháp để cọc ngắn đi 6 m, đỡ phải nén tĩnh lại. Báo cáo khảo sát thì ai khoan lại kiểm tra.”",en:"The piling contractor texts: “Raise the SPT in the sand above 50 and keep the draft stress so the piles get 6 m shorter and we skip another load test. Nobody re-drills to check a site investigation report.”"},options:{safe:{vi:"Không sửa số liệu khảo sát; báo chủ nhiệm địa kỹ thuật và chủ trì thiết kế, phát hành bảng tính đã hiệu chỉnh; nếu muốn tối ưu chiều dài cọc thì đề xuất khoan bổ sung và nén tĩnh cọc thử.",en:"Do not alter investigation data; inform the principal geotechnical engineer and design lead and issue the corrected calculation; to optimize pile length, propose extra boreholes and static load tests on trial piles."},shortcut:{vi:"Sửa SPT và giữ ứng suất nháp như nhà thầu đề nghị để rút ngắn cọc.",en:"Edit the SPT values and keep the draft stress as the contractor asks to shorten the piles."},wait:{vi:"Không sửa, không báo ai và để nhà thầu tự làm việc với đơn vị thiết kế.",en:"Change nothing, tell no one and let the contractor deal with the designer."}},questions:{vi:["Giải thích cách bạn phân loại lớp 2 bằng biểu đồ dẻo và cách tính ứng suất hữu hiệu tại mũi cọc.","Dùng ứng suất tổng hoặc sửa số SPT gây rủi ro gì cho sức chịu tải và độ lún của cọc? Bạn xử lý đề nghị của nhà thầu thế nào?"],en:["Explain how you classified layer 2 on the plasticity chart and how you computed the effective stress at the pile toe.","What risks do total stress or edited SPT values create for pile capacity and settlement? How do you handle the contractor's request?"]},hints:{vi:["Chạy lệnh xem số liệu Atterberg và nhật ký hố khoan, tính chỉ số dẻo trước khi chọn ký hiệu.","Theo SOP mục 3.2, tách phần trên và dưới mực nước ngầm, dùng trọng lượng riêng đẩy nổi cho phần dưới.","SOP mục 4.2: số liệu khảo sát là bằng chứng gốc, không được chỉnh sửa; mọi đề nghị sửa phải báo chủ nhiệm."],en:["Run the Atterberg and borehole log commands and compute the plasticity index before choosing a symbol.","Under SOP 3.2, split the profile above and below groundwater and use the submerged unit weight below it.","SOP 4.2: investigation data is primary evidence and must not be edited; escalate any such request to the principal."]}},learning:{summary:{vi:"Kỹ sư địa kỹ thuật và nền móng lập phương án khảo sát, phân tích số liệu đất đá, đánh giá điều kiện địa chất và thiết kế giải pháp móng nông, móng cọc, xử lý nền, tường chắn và hố đào sâu. Họ quyết định công trình có đứng vững, lún trong giới hạn và an toàn cho công trình lân cận hay không. Nghề đòi hỏi nền tảng cơ học đất vững, kinh nghiệm hiện trường và sự trung thực tuyệt đối với số liệu gốc.",en:"A geotechnical and foundation engineer plans site investigations, analyses soil and rock data, assesses ground conditions and designs shallow foundations, piles, ground improvement, retaining walls and deep excavations. They decide whether a structure stands firm, settles within limits and stays safe for its neighbours. The role requires solid soil mechanics, field experience and absolute honesty with primary data."},responsibilities:{vi:["Lập nhiệm vụ, phương án khảo sát: số lượng, chiều sâu hố khoan và thí nghiệm hiện trường.","Giám sát khoan, lấy mẫu, thí nghiệm SPT, CPT và kiểm tra kết quả thí nghiệm trong phòng.","Phân loại đất, lập mặt cắt địa chất và chọn thông số tính toán đại diện cho từng lớp.","Tính sức chịu tải, độ lún của móng cọc, móng nông và kiểm tra ổn định hố đào.","Thiết kế, giám sát thí nghiệm nén tĩnh cọc và quan trắc lún, nghiêng, nước ngầm."],en:["Define the investigation scope: number and depth of boreholes and in-situ tests.","Supervise drilling, sampling, SPT and CPT tests and check laboratory results.","Classify soils, draw geological sections and select representative design parameters per layer.","Compute capacity and settlement of piles and shallow footings and check excavation stability.","Design and supervise static pile load tests and monitoring of settlement, tilt and groundwater."]},competencies:[{name:{vi:"Cơ học đất",en:"Soil mechanics"},desc:{vi:"Hiểu ứng suất hữu hiệu, cố kết, sức kháng cắt và ứng xử thoát nước, không thoát nước.",en:"Understand effective stress, consolidation, shear strength and drained versus undrained behaviour."}},{name:{vi:"Khảo sát & thí nghiệm",en:"Investigation & testing"},desc:{vi:"Đánh giá chất lượng khoan, lấy mẫu, SPT, CPT, Atterberg và nén cố kết.",en:"Judge the quality of drilling, sampling, SPT, CPT, Atterberg and oedometer tests."}},{name:{vi:"Thiết kế nền móng",en:"Foundation design"},desc:{vi:"Chọn giải pháp móng, tính sức chịu tải và độ lún theo tiêu chuẩn hiện hành.",en:"Select foundation solutions and compute capacity and settlement to current standards."}},{name:{vi:"Phân tích số",en:"Numerical analysis"},desc:{vi:"Dùng phần mềm phần tử hữu hạn, phân tích ổn định mái dốc và tường chắn.",en:"Use finite element software and analyse slope and retaining wall stability."}},{name:{vi:"Trung thực với số liệu",en:"Data integrity"},desc:{vi:"Bảo vệ tính nguyên vẹn của số liệu khảo sát trước áp lực chi phí, tiến độ.",en:"Protect the integrity of investigation data against cost and schedule pressure."}}],knowledge:{vi:["TCVN 10304:2014 - Móng cọc: tiêu chuẩn thiết kế.","TCVN 9362:2012 - Tiêu chuẩn thiết kế nền nhà và công trình.","TCVN 9393:2012 - Cọc: phương pháp thử nghiệm hiện trường bằng tải trọng tĩnh ép dọc trục.","TCVN 9351:2012 - Đất xây dựng: thí nghiệm hiện trường xuyên tiêu chuẩn (SPT).","Hệ thống phân loại đất thống nhất USCS (ASTM D2487) và biểu đồ dẻo Casagrande.","Nguyên lý ứng suất hữu hiệu của Terzaghi: σ' = σ - u."],en:["TCVN 10304:2014 - Pile foundations: design standard.","TCVN 9362:2012 - Design standard for foundations of buildings and structures.","TCVN 9393:2012 - Piles: field test method under axial compressive static load.","TCVN 9351:2012 - Soils for construction: standard penetration test (SPT).","Unified Soil Classification System USCS (ASTM D2487) and the Casagrande plasticity chart.","Terzaghi's effective stress principle: σ' = σ - u."]},tools:["Máy khoan khảo sát và bộ thí nghiệm SPT","Thiết bị xuyên tĩnh CPTu","Phần mềm phần tử hữu hạn địa kỹ thuật","Phần mềm tính sức chịu tải cọc","Thiết bị đo nghiêng và quan trắc lún"],kpis:{vi:["Sai lệch giữa sức chịu tải dự báo và kết quả nén tĩnh cọc thử.","Độ lún công trình thực đo so với giới hạn cho phép.","Tỷ lệ hồ sơ khảo sát đủ số liệu, không phải khoan bổ sung do thiếu sót.","Số sự cố hố đào, công trình lân cận (mục tiêu bằng 0)."],en:["Deviation between predicted capacity and static load test results.","Measured settlement against allowable limits.","Share of investigations complete enough to avoid extra drilling due to gaps.","Excavation or neighbouring building incidents (target zero)."]},day:[{time:"07:30",vi:"Có mặt tại hiện trường kiểm tra khoan, mô tả mẫu và ghi số búa SPT.",en:"Be on site to check drilling, log samples and record SPT blow counts."},{time:"10:00",vi:"Kiểm tra kết quả thí nghiệm trong phòng: giới hạn Atterberg, cắt, nén cố kết.",en:"Check laboratory results: Atterberg limits, shear and oedometer tests."},{time:"13:30",vi:"Lập mặt cắt địa chất, chọn thông số đại diện và tính sức chịu tải cọc.",en:"Draw geological sections, choose representative parameters and compute pile capacity."},{time:"15:30",vi:"Họp với chủ trì kết cấu về chiều dài cọc, cọc thử và chương trình nén tĩnh.",en:"Meet the structural lead on pile length, trial piles and the load test programme."},{time:"17:00",vi:"Hoàn thiện bảng tính, lưu số liệu gốc và nhật ký hiện trường.",en:"Finish calculations and archive raw data and field logs."}],mistakes:{vi:["Dùng ứng suất tổng thay cho ứng suất hữu hiệu dưới mực nước ngầm.","Phân loại sét chỉ theo tên gọi, không kiểm tra giới hạn chảy và đường A.","Ngoại suy số liệu từ hố khoan ở xa cho cả khu đất mà không đánh giá biến động địa tầng."],en:["Using total stress instead of effective stress below the water table.","Classifying clay by name alone without checking the liquid limit and A-line.","Extrapolating a distant borehole to the whole site without assessing stratigraphic variation."]},career:[{vi:"Kỹ sư khảo sát địa chất hiện trường",en:"Site investigation engineer"},{vi:"Kỹ sư địa kỹ thuật",en:"Geotechnical engineer"},{vi:"Chủ trì thiết kế nền móng",en:"Lead foundation engineer"},{vi:"Chuyên gia địa kỹ thuật trưởng",en:"Principal geotechnical specialist"}],glossary:[{term:"Effective stress",vi:"Ứng suất do khung hạt đất chịu, bằng ứng suất tổng trừ áp lực nước lỗ rỗng.",en:"Stress carried by the soil skeleton, equal to total stress minus pore water pressure."},{term:"SPT",vi:"Thí nghiệm xuyên tiêu chuẩn, đếm số búa N để xuyên 30 cm, đánh giá độ chặt hoặc trạng thái đất.",en:"Standard penetration test counting blows N for 30 cm to assess soil density or consistency."},{term:"PI",vi:"Chỉ số dẻo bằng giới hạn chảy trừ giới hạn dẻo, phản ánh phạm vi trạng thái dẻo của đất dính.",en:"Plasticity index equal to liquid limit minus plastic limit, the plastic range of fine soils."},{term:"A-line",vi:"Đường phân chia sét và bụi trên biểu đồ dẻo: PI = 0,73 x (LL - 20).",en:"Line separating clays from silts on the plasticity chart: PI = 0.73 x (LL - 20)."},{term:"Static load test",vi:"Thí nghiệm nén tĩnh cọc theo từng cấp tải để xác định quan hệ tải - lún và sức chịu tải.",en:"Stepwise static loading of a pile to define its load-settlement curve and capacity."}],quiz:[{q:{vi:"Lớp cát dưới mực nước ngầm dày 5 m, γsat = 20 kN/m3, γw = 10 kN/m3. Ứng suất hữu hiệu tăng thêm qua lớp này là bao nhiêu?",en:"A sand layer below groundwater is 5 m thick, γsat = 20 kN/m3, γw = 10 kN/m3. How much does effective stress increase across it?"},options:{vi:["100 kPa","150 kPa","50 kPa","20 kPa"],en:["100 kPa","150 kPa","50 kPa","20 kPa"]},answer:2,explain:{vi:"γ' = 20 - 10 = 10 kN/m3; tăng thêm 10 x 5 = 50 kPa.",en:"γ' = 20 - 10 = 10 kN/m3; the increase is 10 x 5 = 50 kPa."}},{q:{vi:"Mẫu đất hạt mịn có LL = 40% và PI = 22. Theo USCS, ký hiệu phân loại là gì?",en:"A fine-grained soil has LL = 40% and PI = 22. What is its USCS symbol?"},options:{vi:["CL","CH","ML","MH"],en:["CL","CH","ML","MH"]},answer:0,explain:{vi:"Đường A tại LL = 40 là PI = 14,6; PI = 22 nằm trên đường A và LL dưới 50 nên là CL.",en:"The A-line at LL = 40 gives PI = 14.6; PI = 22 lies above it and LL is below 50, so it is CL."}},{q:{vi:"Nhà thầu đề nghị sửa số SPT để rút ngắn chiều dài cọc. Bạn làm gì?",en:"The contractor asks you to edit SPT values to shorten the piles. What do you do?"},options:{vi:["Sửa nhẹ cho hợp lý","Sửa và thêm ghi chú nhỏ","Không phản hồi gì","Từ chối, báo chủ nhiệm và đề xuất khoan bổ sung, nén tĩnh cọc thử"],en:["Edit slightly to look reasonable","Edit and add a small note","Do not respond","Refuse, inform the principal and propose extra boreholes and trial pile load tests"]},answer:3,explain:{vi:"Sửa số liệu khảo sát là làm giả hồ sơ và có thể gây sự cố móng; tối ưu hợp lệ phải dựa trên số liệu bổ sung.",en:"Editing investigation data falsifies records and can cause foundation failure; valid optimization relies on additional data."}},{q:{vi:"Vì sao dưới mực nước ngầm phải dùng trọng lượng riêng đẩy nổi khi tính σ'v?",en:"Why must the submerged unit weight be used below groundwater when computing σ'v?"},options:{vi:["Vì đất dưới nước nhẹ hơn khi khô","Vì áp lực nước lỗ rỗng gánh một phần ứng suất tổng","Vì tiêu chuẩn cho phép bỏ qua nước ngầm","Vì γsat luôn nhỏ hơn γ"],en:["Because soil under water is lighter when dry","Because pore water pressure carries part of the total stress","Because standards allow ignoring groundwater","Because γsat is always below γ"]},answer:1,explain:{vi:"σ' = σ - u; dưới mực nước, áp lực nước lỗ rỗng tăng theo chiều sâu nên khung hạt chỉ chịu γ' = γsat - γw.",en:"σ' = σ - u; below the water table pore pressure grows with depth, so the skeleton carries only γ' = γsat - γw."}}],tools_en:["Site investigation drill rig and SPT kit","CPTu cone penetration test equipment","Geotechnical finite element software","Pile bearing capacity software","Inclinometer and settlement monitoring devices"]}}})})(window.KKR);
